import{_ as r,l as n,o as e,c as i,v as t,p as s,x as l,d as p,i as T,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"温度对推理的影响","description":"","frontmatter":{"title":"温度对推理的影响","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/temperature-reasoning.md","filePath":"llm/temperature-reasoning.md","lastUpdated":1789023840000}'),d={name:"llm/temperature-reasoning.md"};function A(E,a,c,h,u,_){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="温度对推理的影响" tabindex="-1">温度对推理的影响 <a class="header-anchor" href="#温度对推理的影响" aria-label="Permalink to &quot;温度对推理的影响&quot;">​</a></h1><div class="epigraph"><p>自洽需要多样的思维链，多样来自非零温度；把推理任务一律调到贪心，等于关掉投票所依赖的覆盖。</p><footer>—— Wang et al., Self-Consistency Improves Chain of Thought Reasoning, ICLR 2023；温度作为逐步熵见 Holtzman et al., ICLR 2020</footer></div><p><a href="/llm/logit-bias">上一课</a>把逐步仿射钉死。本课把<a href="/llm/sampling-temperature-topp">温度</a>从开放生成的文风旋钮，接到推理任务：思维链、工具调用、数学。主干里 <a href="/llm/self-consistency">Self-Consistency</a> 已经用 \\(T\\gt 0\\) 抽多条链再投票；这里只补缺口——同一 \\(\\pi\\) 上，\\(T=0\\) 与 \\(T=0.7\\) 改变的不只是重复率，还有 <em>能不能碰到正确盆地</em>。后课转向加速：自投机与 Jacobi，默认你会按任务选 \\(T\\)，而不是全局一份 <code>temperature=0</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>产品习惯把「推理 / 代码」设成 \\(T=0\\)，把「聊天」设成 \\(T=0.8\\)。这在单次交付、且任务接近模式匹配时合理：贪心方差小、可复现。多步推理上，正确解往往不是逐步 MAP。早期一步走错，贪心会把错误写圆；略高的温度才能跳出。Wang 等人的自洽明确在 \\(T=0.5\\)–\\(0.7\\) 量级采样。缺口是：单次贪心与多样本采样是两条产品路径，温度必须跟路径走，不能跟「这是推理模型」这个标签走。</p><p>另一侧：温度过高，语法与格式先崩，投票的解析器失败率上升，\\(N\\) 再大也聚合不到答案。推理用的 \\(T\\) 有用区间通常窄于闲聊。代码填空、JSON 工具参数应低温甚至贪心，多样性让给外层的 \\(N\\) 条独立请求，而不是逐步熵。</p><p><span class="marginnote">\\(T=0\\) 在实现里常是 argmax，与极小 \\(T\\) 的并列规则不同。评测脚本若用 <code>temperature=0</code>、线上思考模式用 \\(0.7\\)，比较的是不同策略。先修课已写过这一点，这里只强调它对 pass@k 与自洽的含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把路径分成三档，而不是一个全局 \\(T\\)：</p><ul><li><strong>单次短推理</strong>（分类、工具名、是非）：\\(T=0\\) 或 \\(\\le 0.2\\)，关核或放宽，让文法收支撑。</li><li><strong>单次长思维链、只交一条</strong>：中低 \\(T\\)（约 \\(0.3\\)–\\(0.5\\)）减少胡话，仍留一点跳出局部的可能；不要用闲聊的 \\(0.8\\)。</li><li><strong>要聚合的多样本</strong>：\\(T\\) 与核必须足以产生 <em>答案空间</em> 上的不同 \\(y\\)，而不是标点差。过低则 \\(N\\) 条近似复制，投票无意义；过高则解析失败。从自洽原文的区间出发扫，不要从聊天默认出发。</li></ul><p><a href="/llm/best-of-n">Best-of-N</a> 用外部 \\(s\\) 时，\\(T\\) 还要保证 \\(s\\) 能看见对的候选：过尖的分布让 \\(s\\) 只能在套话里挑。RL rollout 必须接近训练时的 \\(T\\)，否则线上贪心不是训练过的策略。</p>',11)),(e(),s(m,null,{default:l(()=>[T(o,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E4%BB%BB%E5%8A%A1%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20A%5B%22%E5%8D%95%E6%AC%A1%E7%9F%AD%3A%20T%E2%86%920%22%5D%0A%20%20TASK%20--%3E%20B%5B%22%E5%8D%95%E6%AC%A1%E9%95%BF%E9%93%BE%3A%20%E4%B8%AD%E4%BD%8E%20T%22%5D%0A%20%20TASK%20--%3E%20C%5B%22%E5%A4%9A%E6%A0%B7%E6%9C%AC%E8%81%9A%E5%90%88%3A%20%E4%B8%AD%20T%20%2B%20%E6%A0%B8%22%5D%0A%20%20C%20--%3E%20V%5B%22%E7%AD%94%E6%A1%88%E7%A9%BA%E9%97%B4%E6%8A%95%E7%A5%A8%22%5D%0A%20%20A%20--%3E%20G%5B%22%E6%96%87%E6%B3%95%E6%94%B6%E6%94%AF%E6%92%91%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>温度改熵、不删 token；核才删。推理失败有两种：没覆盖到正确链，以及覆盖到了但格式坏掉。前者要升高 \\(T\\) 或加 \\(N\\)，后者要降低 \\(T\\) 或加约束。经验上的「推理用低温」只覆盖第二种。Renze 与 Guven 等后续测量表明：在若干多选题上，中等温度区间内准确率可以相对平坦——这不是允许乱设 \\(T\\)，而是警告：不要把某一基准上的平坦区间写成普适定律。思维链长度随 \\(T\\) 变：高温往往写得更长、更散，延迟账单与质量账单绑在一起。</p><p><span class="marginnote">投机解码的接受率随 \\(T\\) 升高而下降。思考模式开高 \\(T\\) 时，加速比要用同一 \\(T\\) 测，不能用贪心加速比宣传。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把温度交给最终用户无上界拉高还不截断。不要用 \\(T=0\\) 的单链准确率与 \\(T=0.7,N=16\\) 的自洽比「模型变强了」——多的是测试时计算。种子在张量并行下不可比特级复现，推理回归测试不要依赖 \\(T\\gt 0\\) 的逐 token 对齐。</p><p>出处：Wang et al., ICLR 2023；Holtzman et al., ICLR 2020。后续温度敏感性测量以各自论文的任务集为准，不发明编号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>推理路径决定 \\(T\\)：单次短用贪心，多样本聚合必须非零温度。</li><li>自洽与 BoN 的 \\(N\\) 在 \\(T\\to 0\\) 时退化成复制。</li><li>过高 \\(T\\) 先打崩解析，再谈覆盖无意义。</li><li>评测、RL、投机接受率都必须钉同一 \\(T\\)。</li><li>「推理模型所以 \\(T=0\\)」不是定理。</li><li>后课把逐步熵放下，改加速：不用第二模型的投机。</li><li>出处：Wang et al., ICLR 2023；Holtzman et al., ICLR 2020。</li></ul>',8))])}const g=r(d,[["render",A]]);export{f as __pageData,g as default};
